library ieee; use ieee.std_logic_1164.all;
entity bbq_crc16_core is generic(DATA_WIDTH:positive:=8;POLY:std_logic_vector(15 downto 0):=x"1021";INIT:std_logic_vector(15 downto 0):=x"FFFF");port(clk,rst_n,clear,data_valid:in std_logic;data_in:in std_logic_vector(DATA_WIDTH-1 downto 0);crc_out:out std_logic_vector(15 downto 0);crc_valid:out std_logic);end;
architecture rtl of bbq_crc16_core is signal c:std_logic_vector(15 downto 0):=INIT;signal v:std_logic:='0';function next_crc(d:std_logic_vector;c0:std_logic_vector(15 downto 0))return std_logic_vector is variable x:std_logic_vector(15 downto 0):=c0;variable fb:std_logic;begin for i in d'range loop fb:=x(15) xor d(i);x:=x(14 downto 0)&'0';if fb='1'then x:=x xor POLY;end if;end loop;return x;end;begin crc_out<=c;crc_valid<=v;process(clk)begin if rising_edge(clk)then v<='0';if rst_n='0' or clear='1'then c<=INIT;elsif data_valid='1'then c<=next_crc(data_in,c);v<='1';end if;end if;end process;end architecture;
